def copy_legacy_fbr_submissions(apps, schema_editor):
    """Fold legacy FbrInvoiceSubmission AR rows into canonical EInvoiceSubmission."""
    import json

    Legacy = apps.get_model("finance", "FbrInvoiceSubmission")
    EInv = apps.get_model("finance", "EInvoiceSubmission")
    Invoice = apps.get_model("finance", "CustomerInvoice")
    status_map = {
        "draft": "draft",
        "queued": "pending",
        "submitted": "submitted",
        "accepted": "accepted",
        "rejected": "rejected",
    }

    def _load(raw):
        try:
            data = json.loads(raw) if raw else {}
            return data if isinstance(data, dict) else {"value": data}
        except ValueError:
            return {"raw": raw}

    for row in Legacy.objects.filter(invoice_type="ar"):
        key = (row.local_invoice_id or "").strip()
        inv = None
        if key.isdigit():
            inv = Invoice.objects.filter(
                organization_id=row.organization_id, pk=int(key)
            ).first()
        if inv is None:
            inv = Invoice.objects.filter(
                organization_id=row.organization_id, invoice_no=key
            ).first()
        if inv is None:
            continue
        if EInv.objects.filter(organization_id=row.organization_id, ar_invoice=inv).exists():
            continue
        EInv.objects.create(
            organization_id=row.organization_id,
            ar_invoice=inv,
            fbr_status=status_map.get(row.status, "draft"),
            fbr_invoice_no=row.fbr_invoice_no,
            payload_json=_load(row.payload_json),
            response_json=_load(row.response_json),
            submitted_at=row.submitted_at,
            mode="legacy",
        )

